        const auto& a = boxes[i];
        const auto& b = boxes[j];
        if (a.Max.x >= b.Min.x && b.Max.x >= a.Min.x &&
            a.Max.y >= b.Min.y && b.Max.y >= a.Min.y &&
            a.Max.z >= b.Min.z && b.Max.z >= a.Min.z) {
            result.emplace_back(i,j);
        }
    }
}
return result;

